// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address k, bool s) public {
        // _contractOwner is never assigned, so the only owner is address(0).
        vm.assume(k != address(0));

        vm.startPrank(address(0));
        c.setApprovedLogger(k, s);
        c.setApprovedLogger(k, !s);
        vm.stopPrank();

        // Rule: after setting k to s and then to !s, k must hold exactly !s.
        assertTrue(c.approvedLoggers(k) == !s, "logger flag must equal the last written status");
    }
}
